def preencher(apps, schema_editor):
    """Preço contratado = preço actual do plano; destaque = Premium; estado dos códigos."""
    Plano = apps.get_model('subscriptions', 'SubscriptionPlan')
    Sub = apps.get_model('subscriptions', 'UserSubscription')
    Codigo = apps.get_model('subscriptions', 'PromotionalCode')
    for plano in Plano.objects.exclude(plan_type='FREE'):
        Sub.objects.filter(plan=plano, preco_mensal_kz__isnull=True).update(
            preco_mensal_kz=int(plano.monthly_price or 0),
            preco_anual_kz=int(plano.yearly_price) if plano.yearly_price else None,
        )
    if not Plano.objects.filter(destaque=True).exists():
        Plano.objects.filter(plan_type='PREMIUM').update(destaque=True)
    # Decisão do dono: 7 dias de Premium grátis (alterável na administração)
    Plano.objects.filter(plan_type='PREMIUM', dias_teste=0).update(dias_teste=7)
    Codigo.objects.filter(is_active=False).update(estado='desligado')
    Codigo.objects.filter(is_active=True).update(estado='activo')


